const BASE = 'https://cinehdplus.org';
function getStreams(tmdbId, mediaType, season, episode) {
  try {
    const tipo = mediaType === 'movie' ? 'movie' : 'tv';
    const datos = await datosTmdb(tmdbId, tipo);
    if (!datos) return [];
    const temporada = Number(season) || 1;
    const episodio = Number(episode) || 1;

    const encontrada = await buscarPagina(datos, tipo);
    if (!encontrada) return [];
    let pagina = encontrada.href;
    let html = encontrada.html;
    if (tipo === 'tv') {
      pagina = paginaEpisodio(html, temporada, episodio);
      if (!pagina) return [];
      html = await texto(pagina, { headers: { Referer: `${BASE}/` }, limite: 12000 });
    }

    const items = await enlaces(pagina, html);
    if (!items.length) return [];
    return await armarCine(items, FUENTE);
  } catch (e) {
    console.log(`[${FUENTE}] ${e.message}`);
    return [];
  }
}

module.exports = { getStreams: limitar(getStreams) };
